const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-112.246886, 34.498828]);
  // 50 miles in meters (1 mile = 1609.34 meters)
  const bufferDistance = 50 * 1609.34;
  const region = point.buffer(bufferDistance);

  const startDate = '2017-06-20';
  const endDate = '2017-06-30';

  // 2. Data Acquisition - Try VIIRS Active Fires first
  let fireCollection = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML')
    .filterDate(startDate, endDate)
    .filterBounds(region);

  let collectionSize = fireCollection.size().getInfo();
  console.log(`VIIRS fire collection size: ${collectionSize}`);

  // If no VIIRS data, try MODIS as fallback
  if (collectionSize === 0) {
    console.log("Trying MODIS MCD14DL as fallback...");
    fireCollection = ee.ImageCollection('MODIS/006/MCD14DL')
      .filterDate(startDate, endDate)
      .filterBounds(region);
    collectionSize = fireCollection.size().getInfo();
    console.log(`MODIS fire collection size: ${collectionSize}`);
  }

  // Check for empty collection
  if (collectionSize === 0) {
    console.log("No fire detection data found for the specified date and location.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Count fire pixels
  // For VIIRS: Use 'FireMask' band (3=fire, 2=background, etc.)
  // For MODIS: Use 'confidence' band (>0 indicates fire)
  let fireDetected = false;
  let totalFirePixels = 0;

  // Get the list of image IDs to iterate
  const imageList = fireCollection.toList(collectionSize);

  for (let i = 0; i < collectionSize; i++) {
    const image = ee.Image(imageList.get(i));
    let fireMask;

    // Check which collection we're using
    const bandNames = image.bandNames().getInfo();

    if (bandNames.includes('FireMask')) {
      // VIIRS: FireMask = 3 indicates fire
      fireMask = image.select('FireMask').eq(3);
    } else if (bandNames.includes('confidence')) {
      // MODIS: confidence > 0 indicates fire (30=low, 60=nominal, 90=high)
      fireMask = image.select('confidence').gt(0);
    } else if (bandNames.includes('MaxFRP')) {
      // MODIS MCD14DL: MaxFRP > 0 indicates fire
      fireMask = image.select('MaxFRP').gt(0);
    } else {
      console.log(`Image ${i}: No fire detection band found`);
      continue;
    }

    // Count fire pixels in the region
    const countResult = fireMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: 1000,  // Use 1km scale for efficiency
      maxPixels: 1e9,
      bestEffort: true
    });

    const fireCount = countResult.get(fireMask.bandNames().get(0)).getInfo();

    if (fireCount !== null && fireCount > 0) {
      console.log(`Image ${i} (${image.date().format('YYYY-MM-dd').getInfo()}): ${fireCount} fire pixels detected`);
      totalFirePixels += fireCount;
      fireDetected = true;
    }
  }

  console.log(`Total fire pixels detected in region: ${totalFirePixels}`);

  // 4. Validation & Final Answer
  if (totalFirePixels > 0) {
    console.log("<answer>A</answer>");
  } else if (totalFirePixels === 0) {
    console.log("<answer>B</answer>");
  } else {
    // This would happen if fireCount was null or negative
    console.log("<answer>C3</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error("Initialization error:", e);
  console.log("<answer>D</answer>");
});
